#!/usr/bin/env python3
"""Turn 35 Wave 102: CLOSE THE GAME TO UNDO AN INJURY, AND THE COMPLETE CULT HEROES MAP.

Wave 102's centrepieces:

1. CLOSE THE GAME TO UNDO AN INJURY - and it undoes cards too. Close the app after an
   injury, a yellow, or a red, and reopening resumes at the last stoppage before it (goal
   kick, free kick, corner, throw-in, or half-time). It does NOT work for penalties. That is
   a second save-based undo alongside the Save Mode trick from wave 101, and together they
   mean the only permanent record in DLS is the one you choose to keep.

2. THE COMPLETE CULT HEROES MAP, which the corpus had only half of. The corpus knew about the
   three Season Passes at two heroes each; this wave adds the other two routes - **three Cult
   Heroes from Online Events**, and **up to three per Dream Draft** across one free and two
   paid drafts. So the collection is obtainable without money through three separate systems,
   and the official wording confirms all three.

3. THE PRIZE LADDER CARRIES UNREDEEMED REWARDS FORWARD, which gives the corpus's "never release
   a Classic Player" rule a mechanism at last. If you do not finish a ladder, the unredeemed
   specials are still in the pool for the next one - but the pool is randomised, so missing one
   ladder's card means it can appear in the next while the new cards appear too. That is why
   releasing is a double loss.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w102')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_in=new_ev("r/DreamLeagueSoccer zmglpx (15 Dec 2022 - the injury-proof substitution exploit, with JoYou_02's close-and-reopen undo for injuries, yellow cards and red cards but not penalties), r/DreamLeagueSoccer 18ruojk (the legendary physio being cheaper than gems and healing all injured players, and the training-before-medical facility priority), LevelWinner DLS2020 advanced guide (3 Jul 2020 - the penalty-fishing injury risk, the cross-next-to-the-stamina-bar injury indicator, the sub-them-out-immediately rule, and the 15-gem knee-strain heal for three matches), supercheats.com Q&A (3 Mar 2017 - the click-the-player-then-heal dialogue that shows the matches needed to recover), dreamleagueforall.wordpress.com (19 Nov 2016 - the battery-icon heal UI and the scaled coin cost), keengamer.com (25 Sep 2022 - turning the game off mid-season to fully replenish energy), sakibpro.com 'DLS 26 New Update' (20 Aug 2026 - the complete Cult Heroes acquisition map across Season Passes, Online Events and Dream Draft, plus the new Season Pass Players card type), r/DreamLeagueSoccer 1t00sal 'All Types of Cards in Dream League Soccer' (30 Apr 2026 - the card types in one squad with their sources, and the green TOTY cards), r/DreamLeagueSoccer 1hlt0l2 'Special Players PSA' (25 Dec 2024 - the Prize Ladder carry-over randomisation and the do-not-release rule), r/DreamLeagueSoccer 1ub136q (20 Jun 2026 - the official World Heroes / World Winners video title and description), the official DLS TikTok (World Heroes available now via Legendary Agents; Cult Heroes from 16 September via Cult Hero Agents in Events, Drafts and the Season Pass; the Italian League Classics on the Prize Ladder), gamedls.net (27 Aug 2025 - releasing a special player yields one special coach), sakibpro.com squad builder (special cards cannot be bought with coins in the standard transfer market)",
    "THE CLOSE-AND-REOPEN UNDO, THE COMPLETE CULT HEROES MAP, AND THE PRIZE LADDER CARRY-OVER. (1) THE CLOSE-AND-REOPEN UNDO: '**I will just close my game if my player got injured, then open it again. The game will resume at the last time stop before the injury** (goal kick, free kick, corner kick, throw in, or half time). **Can also work for yellow cards and red cards, but not for penalties.**' So an injury, a booking and a sending-off can all be undone by closing the app - a second save-based undo alongside the Save Mode trick, and together they mean the only permanent record in DLS is the one you choose to keep. (2) THE LEGENDARY PHYSIO BEATS GEMS FOR INJURIES: '**you can use the legendary physio. It's cheaper than using gems and it heals all injured players**' - with the facility priority attached: '**I would focus on upgrading my training facility before the medical facility.**' (3) THE INJURY INDICATOR AND THE SUB RULE: 'their stamina bar will be nearly depleted - you will also see **a small cross next to the stamina bar** telling you that they're hurt. You will also notice that they move much slower... **When this happens, sub them out immediately!** You don't want to be playing as if you're one man short.' And the priced example: '**It costs 15 gems to make him recover from the knee strain that's set to keep him out for the next three matches.**' (4) THE INJURY DURATION LOOKUP: '**Place your injured player onto substitution. To check the matches he needs in order to recover, simply click on the player and then click on heal, a dialogue box will pop up with the information.**' So the games-out figure is readable on demand, which pairs with the corpus's ephemeral-injury-report finding. (5) THE PENALTY-FISHING INJURY RISK: '**playing aggressively close to the goal is a great way to fish for penalties, but it's also a shortcut to injuries** that could force your top sources of offense to sit it out for at least a few games.' So the attacking style that creates penalties also creates injuries - a genuine trade-off. (6) THE COMPLETE CULT HEROES MAP, which the corpus had only half of. The corpus knew about the three Season Passes at two heroes each (CLAIM-1553); this adds the other two routes: '**Online Events:** A total of **3 Cult Heroes** will be exclusively available as top-tier rewards by winning matches in upcoming Online Events' and '**Dream Draft:** There will be **1 Free Draft and 2 Paid Drafts** available. In *every single draft*, lucky managers have the chance to secure up to **3 Cult Heroes** to permanently add to their squads.' The official wording confirms all three: '**Cult Heroes are coming to #DLS26 on September 16th. Find them by collecting Cult Hero Agents, available in Events, Drafts and the Season Pass.**' **So the collection is obtainable without money through three separate systems.** (7) THE NEW SEASON PASS PLAYERS CARD TYPE: 'For the first time, **exclusive player cards are being introduced directly through the Season Pass system**! The Season Pass cards will feature special agents and players distributed across both the Free and Premium tiers.' (8) THE TOTY CARDS ARE GREEN, and named: '**TOTY Yamal & Pedri: The brilliant green cards to complete the squad**' - so TOTY is a confirmed DLS26 card type with a green colour, sitting outside the corpus's five-colour taxonomy. (9) THE PRIZE LADDER CARRY-OVER, which gives the corpus's never-release rule a mechanism at last: '**Don't release any specials even if it's suker. Reason is when they release new special players like ronaldinho or r9, the players will most likely be rewards on the prize ladder, and players will be randomized. So if you don't get all classic players by the end of the ladder, you have a chance of getting them in the next ladder and miss out on the other newly released classic players.**' **So unredeemed specials stay in the pool, but the pool is randomised - which is why releasing is a double loss.** (10) THE WORLD HEROES OFFICIAL ROUTE: '**DLS26 World Heroes are available now. Every time you use a Legendary Agent, you have a chance of getting a World Hero Special Player**' - official confirmation of the agent route - and the origin: '**One tournament, two new special cards**' for World Heroes and World Winners. (11) THE ITALIAN LEAGUE CLASSICS, officially confirmed: 'Get your hands on **Trezeguet, Batistuta, Crespo and Desailly** in the form of special Classic Player cards' on the Prize Ladder. (12) RELEASING A SPECIAL PLAYER yields **1 special coach card** - a second rung on the release mapping.",
    "CLOSE THE GAME TO UNDO AN INJURY - and it undoes yellow and red cards too, resuming at the last stoppage before the event. It does NOT work for penalties. That is a second save-based undo alongside the Save Mode trick, and together they mean the only permanent record in DLS is the one you choose to keep. THE LEGENDARY PHYSIO IS CHEAPER THAN GEMS and heals all injuries at once. THE COMPLETE CULT HEROES MAP: 6 from three Season Passes (2 each, one free one paid), 3 from Online Events, and up to 3 per Dream Draft across 1 free and 2 paid drafts - three money-free routes, officially confirmed. THE NEW SEASON PASS PLAYERS CARD TYPE. THE TOTY CARDS ARE GREEN and named (Yamal, Pedri) - a colour outside the corpus's five-colour taxonomy. AND THE PRIZE LADDER CARRIES UNREDEEMED SPECIALS FORWARD with a randomised pool, which is the mechanism behind the corpus's never-release rule.",
    "THE INJURY UNDO, THE CULT HEROES MAP, AND THE LADDER CARRY-OVER",
    quality="community")

add_claim("CLOSE THE GAME TO UNDO AN INJURY - and it undoes cards too: '**I will just close my game if my player got injured, then open it again. The game will resume at the last time stop before the injury** (goal kick, free kick, corner kick, throw in, or half time). **Can also work for yellow cards and red cards, but not for penalties.**' **So an injury, a booking and a sending-off can all be undone by closing the app** - a second save-based undo alongside the Save Mode trick, and together they mean the only permanent record in DLS is the one you choose to keep.", 3, "injuries/close-and-reopen-undo", [e_in], notes="A second save-based undo; pairs with the Save Mode trick from wave 101")
add_claim("THE LEGENDARY PHYSIO BEATS GEMS FOR INJURIES: '**you can use the legendary physio. It's cheaper than using gems and it heals all injured players**' - with the facility priority attached: '**I would focus on upgrading my training facility before the medical facility.**' So a squad-wide injury is cheaper to clear with one coin physio than with per-player gems, which is the corpus's no-gem-healing rule with a priced alternative.", 3, "injuries/legendary-physio-cheaper-than-gems", [e_in])
add_claim("THE INJURY INDICATOR AND THE SUB RULE: 'their stamina bar will be nearly depleted - you will also see **a small cross next to the stamina bar** telling you that they're hurt. You will also notice that they move much slower... **When this happens, sub them out immediately!** You don't want to be playing as if you're one man short.' And the priced example: '**It costs 15 gems to make him recover from the knee strain that's set to keep him out for the next three matches.**'", 3, "injuries/indicator-and-sub-immediately", [e_in])
add_claim("THE INJURY DURATION LOOKUP: '**Place your injured player onto substitution. To check the matches he needs in order to recover, simply click on the player and then click on heal, a dialogue box will pop up with the information.**' **So the games-out figure is readable on demand** - which pairs with the corpus's ephemeral-injury-report finding: the report vanishes, but the heal dialogue will tell you the duration whenever you check.", 3, "injuries/duration-lookup-via-heal-dialogue", [e_in])
add_claim("THE PENALTY-FISHING INJURY RISK: '**playing aggressively close to the goal is a great way to fish for penalties, but it's also a shortcut to injuries** that could force your top sources of offense to sit it out for at least a few games.' So the attacking style that creates penalties also creates injuries - a genuine trade-off, and a reason the corpus's corner routine (which scores without contact) is the safer high-percentage route.", 3, "injuries/penalty-fishing-injury-risk", [e_in])
add_claim("THE COMPLETE CULT HEROES MAP, which the corpus had only half of. The corpus knew the three Season Passes at two heroes each; this adds the other two routes: '**Online Events:** A total of **3 Cult Heroes** will be exclusively available as top-tier rewards by winning matches in upcoming Online Events' and '**Dream Draft:** There will be **1 Free Draft and 2 Paid Drafts** available. In every single draft, lucky managers have the chance to secure up to **3 Cult Heroes** to permanently add to their squads.' **The official wording confirms all three** - 'Cult Hero Agents, available in Events, Drafts and the Season Pass' - so the collection is obtainable without money through three separate systems.", 3, "cards/cult-heroes-complete-map", [e_in], notes="Extends CLAIM-1553 with the Online Events and Dream Draft routes")
add_claim("THE NEW SEASON PASS PLAYERS CARD TYPE: 'For the first time, **exclusive player cards are being introduced directly through the Season Pass system**! The Season Pass cards will feature special agents and players distributed across both the Free and Premium tiers.' **So the Season Pass now carries cards, not just consumables** - which is a new reason the pass decision matters, and it sits beside the corpus's Season Pass contents gap.", 3, "cards/season-pass-players-card-type", [e_in])
add_claim("THE TOTY CARDS ARE GREEN, and named: '**TOTY Yamal & Pedri: The brilliant green cards to complete the squad**' - so TOTY (Team of the Year) is a confirmed DLS26 card type with a **green** colour, sitting outside the corpus's five-colour taxonomy (gold, black, purple, blue, orange). A colour the corpus did not have.", 3, "cards/toty-green-cards", [e_in], notes="A sixth card colour the corpus's taxonomy lacked")
add_claim("THE PRIZE LADDER CARRY-OVER, which gives the corpus's never-release rule a mechanism at last: '**Don't release any specials even if it's suker. Reason is when they release new special players like ronaldinho or r9, the players will most likely be rewards on the prize ladder, and players will be randomized. So if you don't get all classic players by the end of the ladder, you have a chance of getting them in the next ladder and miss out on the other newly released classic players.**' **So unredeemed specials stay in the pool, but the pool is randomised - which is why releasing is a double loss: you lose the card AND your place in the draw.**", 3, "prizeladder/carry-over-randomisation", [e_in], notes="The mechanism behind the corpus's never-release-a-Classic rule")
add_claim("THE WORLD HEROES OFFICIAL ROUTE: '**DLS26 World Heroes are available now. Every time you use a Legendary Agent, you have a chance of getting a World Hero Special Player**' - official confirmation of the agent route - and the origin: '**One tournament, two new special cards**' for World Heroes and World Winners. So the two World collections came from a single event, which is why they share a window.", 3, "cards/world-heroes-official-agent-route", [e_in])
add_claim("THE ITALIAN LEAGUE CLASSICS, officially confirmed with names: 'Get your hands on **Trezeguet, Batistuta, Crespo and Desailly** in the form of special Classic Player cards' on the Prize Ladder - the official TikTok wording behind the corpus's Prize Ladder Classics finding, and the set Desailly belongs to (the named best 5x100 first pick).", 3, "prizeladder/italian-league-classics-official", [e_in])
add_claim("RELEASING A SPECIAL PLAYER yields **1 special coach card** - a second rung on the release mapping (common to Common coach, 80+ to Rare, special to Special), and a reminder that the corpus's coach-farming loop has a special-player variant that costs a card.", 3, "coaching/release-special-yields-special-coach", [e_in])
add_claim("SPECIAL CARDS CANNOT BE BOUGHT WITH COINS in the standard transfer market: '**Special edition cards such as Champion, World Cup Heroes, or Dreamstars are obtained exclusively through special agents, events, or season passes. Because they cannot be bought directly with regular coins in the standard transfer market, their coin value is nullified in the budget calculator.**' So the transfer market and the special-card economy are separate systems, which is the corpus's two-lane acquisition model confirmed from a third angle.", 3, "transfers/special-cards-not-in-transfer-market", [e_in])

for p in ['EV-515_injury_undo.html','EV-515b_cult_heroes_and_cards.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
